{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Client' GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM abnormal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Client' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Order-other's own DB client spans (SELECT/INSERT ts.orders_other) rose from about 0.4 ms to about 416 ms p95, with no error status."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, span_name, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM normal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Internal' AND span_name IN ('OrderOtherRepository.findByAccountId','OrderOtherController.queryOrdersForRefresh') GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, round(quantile_cont(duration,0.95)/1e6,2) FROM abnormal_traces WHERE service_name='ts-order-other-service' AND attr_span_kind='Internal' AND span_name IN ('OrderOtherRepository.findByAccountId','OrderOtherController.queryOrdersForRefresh') GROUP BY 1,2",
          "claim": "Repository and controller spans grew from about 1-2 ms to about 420 ms, tracking the slow DB client calls."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abnormal' AS period, metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-order-other-service%' AND metric IN ('k8s.pod.cpu.usage','k8s.pod.memory.working_set','k8s.pod.memory.page_faults') GROUP BY 1,2",
          "claim": "Order-other pod CPU and memory stayed low and flat during the incident, so the slowdown is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, span_name, attr_span_kind, round(quantile_cont(duration,0.95)/1e6,2) p95_ms FROM normal_traces WHERE service_name='ts-seat-service' AND span_name IN ('POST','POST /api/v1/seatservice/seats/left_tickets') GROUP BY 1,2,3 UNION ALL SELECT 'abnormal', span_name, attr_span_kind, round(quantile_cont(duration,0.95)/1e6,2) FROM abnormal_traces WHERE service_name='ts-seat-service' AND span_name IN ('POST','POST /api/v1/seatservice/seats/left_tickets') GROUP BY 1,2,3",
          "claim": "Seat-service's calls to order-other rose from about 4.5 ms to about 215 ms p95, and its left_tickets server span rose to about 221 ms."
        }
      ]
    },
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-admin-order-service' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Admin-order server spans reached 500-1500 ms p95 during the incident, while its own work stayed near normal."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel2-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' AS period, service_name, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2 UNION ALL SELECT 'abnormal', service_name, round(quantile_cont(duration,0.95)/1e6,1) FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY 1,2",
          "claim": "Travel2's trips/left server span rose to about 43 ms p95 from a lower normal baseline, as it waits on seat-service."
        }
      ]
    },
    {
      "from": "ts-travel2-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' AS period, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name IN ('GET /api/v1/adminorderservice/adminorder','DELETE /api/v1/adminorderservice/adminorder/{orderId}/{trainNumber}') GROUP BY 1,2",
          "claim": "Dashboard requests to the admin-order path reached about 500-880 ms p95, the user-facing symptom of the slow chain."
        }
      ]
    }
  ]
}
